import React from 'react';

const LOGO_DATA_URL = "data:image/png;base64,";

interface LogoProps {
  className?: string;
}

export default function Logo({ className = "h-12 w-auto" }: LogoProps) {
  return (
    <img 
      src={LOGO_DATA_URL} 
      alt="Elixir Business School Logo" 
      className={"object-contain shrink-0 " + (className || "")}
    />
  );
}
